-- ChubbyLu Bakery POS v0.13.0 — cost snapshots and profitability
alter table public.products add column if not exists cost_price numeric(12,2) not null default 0 check(cost_price>=0);
alter table public.sale_items add column if not exists unit_cost_snapshot numeric(12,2) not null default 0 check(unit_cost_snapshot>=0);

create or replace function public.snapshot_sale_item_cost() returns trigger language plpgsql security definer set search_path=public as $$begin select cost_price into new.unit_cost_snapshot from public.products where id=new.product_id and shop_id=new.shop_id;new.unit_cost_snapshot:=coalesce(new.unit_cost_snapshot,0);return new;end $$;
drop trigger if exists sale_item_cost_snapshot_trigger on public.sale_items;create trigger sale_item_cost_snapshot_trigger before insert on public.sale_items for each row execute function public.snapshot_sale_item_cost();

create or replace function public.get_profitability_report(p_from date,p_to date) returns jsonb language plpgsql security definer stable set search_path=public as $$
declare v_shop uuid:=public.current_shop_id();
begin if auth.uid() is null or not public.is_admin() then raise exception 'Administrator access required';end if;if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise exception 'Invalid profitability date range';end if;
return jsonb_build_object(
'summary',(with sales_summary as(select coalesce(sum(subtotal-discount),0) revenue from public.sales where shop_id=v_shop and created_at::date between p_from and p_to),refund_summary as(select coalesce(sum(subtotal-discount),0) revenue from public.sale_refunds where shop_id=v_shop and created_at::date between p_from and p_to),sold_cost as(select coalesce(sum(si.qty*si.unit_cost_snapshot),0) cost,count(*) filter(where si.unit_cost_snapshot>0) costed,count(*) filter(where si.unit_cost_snapshot=0) uncosted from public.sale_items si join public.sales s on s.id=si.sale_id where si.shop_id=v_shop and s.created_at::date between p_from and p_to),returned_cost as(select coalesce(sum(ri.qty*si.unit_cost_snapshot),0) cost from public.sale_refund_items ri join public.sale_items si on si.id=ri.sale_item_id join public.sale_refunds r on r.id=ri.refund_id where ri.shop_id=v_shop and r.created_at::date between p_from and p_to),expense_summary as(select coalesce(sum(amount),0) total from public.expenses where shop_id=v_shop and expense_date between p_from and p_to) select jsonb_build_object('net_sales',ss.revenue-rs.revenue,'net_cogs',sc.cost-rc.cost,'gross_profit',(ss.revenue-rs.revenue)-(sc.cost-rc.cost),'expenses',es.total,'operating_result',(ss.revenue-rs.revenue)-(sc.cost-rc.cost)-es.total,'gross_margin_percent',case when ss.revenue-rs.revenue=0 then 0 else (((ss.revenue-rs.revenue)-(sc.cost-rc.cost))/(ss.revenue-rs.revenue))*100 end,'costed_items',sc.costed,'uncosted_items',sc.uncosted) from sales_summary ss,refund_summary rs,sold_cost sc,returned_cost rc,expense_summary es),
'products',(with sold as(select si.product_id,si.product_name,sum(si.qty) qty,sum(si.line_total) revenue,sum(si.qty*si.unit_cost_snapshot) cost from public.sale_items si join public.sales s on s.id=si.sale_id where si.shop_id=v_shop and s.created_at::date between p_from and p_to group by si.product_id,si.product_name),returned as(select ri.product_id,sum(ri.qty) qty,sum(ri.line_total) revenue,sum(ri.qty*si.unit_cost_snapshot) cost from public.sale_refund_items ri join public.sale_items si on si.id=ri.sale_item_id join public.sale_refunds r on r.id=ri.refund_id where ri.shop_id=v_shop and r.created_at::date between p_from and p_to group by ri.product_id),result as(select s.product_name,s.qty-coalesce(r.qty,0) qty_sold,s.revenue-coalesce(r.revenue,0) net_revenue,s.cost-coalesce(r.cost,0) net_cost,(s.revenue-coalesce(r.revenue,0))-(s.cost-coalesce(r.cost,0)) gross_profit,case when s.revenue-coalesce(r.revenue,0)=0 then 0 else (((s.revenue-coalesce(r.revenue,0))-(s.cost-coalesce(r.cost,0)))/(s.revenue-coalesce(r.revenue,0)))*100 end margin_percent from sold s left join returned r on r.product_id=s.product_id) select coalesce(jsonb_agg(to_jsonb(result) order by gross_profit desc),'[]'::jsonb) from result));end $$;
revoke all on function public.get_profitability_report(date,date) from public;grant execute on function public.get_profitability_report(date,date) to authenticated;
